const TERMS_TR: LegalDoc = {
  title: "Swipedia Kullanım Koşulları",
  sections: [
    { t: "1. Swipedia Hakkında", b: "Swipedia; kullanıcıların kaydırma tabanlı bir arayüz üzerinden soruları keşfetmesine, yanıtlamasına, incelemesine ve sorularla etkileşime geçmesine olanak tanıyan etkileşimli, bilgi ve soru temelli bir uygulamadır. Öncelikle fotoğraf veya video sunan geleneksel sosyal medya platformlarının aksine Swipedia; esas olarak sorular, testler, eğitici içerikler, bilgi yarışması soruları ve diğer bilgi temelli materyaller sunar. Kullanıcılar soruları kaydırabilir, uygun olduğunda yanıt seçebilir, geri bildirim alabilir, etkinliklerini takip edebilir ve Hizmet'in sunduğu çeşitli özelliklerle etkileşime geçebilir. Swipedia; kullanıcı etkileşimleri, seçilen ilgi alanları, önceki yanıtlar, etkileşim düzeyi, dil, tercihler ve izin verilen diğer bilgiler gibi etkenlere göre kullanıcıya sunulan soruları kişiselleştirebilir veya düzenleyebilir. Swipedia, özellikleri istediği zaman ekleyebilir, kaldırabilir, değiştirebilir veya durdurabilir." },
    { t: "2. Uygunluk", b: "Swipedia'yı kullanmak için ülkende geçerli olan asgari yaş şartını karşılamalısın. Geçerli hukuk daha yüksek bir asgari yaş gerektirmedikçe kullanıcıların en az 13 yaşında olması gerekir. Bazı özelliklerin ek yaş şartları olabilir. Sana uygulanan hukuka göre veri işlemeye bağımsız olarak rıza gösterme yaşının altındaysan, gerektiğinde Swipedia'yı yalnızca ebeveynin veya yasal vasinin bilgisi ve izniyle kullanmalısın. Swipedia'yı kullanarak; geçerli asgari yaş şartını karşıladığını, bu Koşullar'a taraf olma ehliyetine sahip olduğunu ve kullanımının sana uygulanan hiçbir yasayı ihlal etmediğini beyan edersin. Kullanıcının geçerli yaş şartlarını karşılamadığına makul şekilde inanırsak hesabı kısıtlayabilir veya kapatabiliriz." },
    { t: "3. Hesap Kaydı", b: "Bazı özellikler hesap oluşturmanı gerektirebilir. Hesap oluştururken doğru, güncel ve eksiksiz bilgi vermeyi kabul edersin. Hesap bilgilerinin gizliliğini korumaktan ve hesabın üzerinden gerçekleşen etkinliklerden sen sorumlusun. Şunları yapmamalısın:\n• Başka birinin kimliğini kullanarak hesap oluşturmak;\n• Yanlış veya yanıltıcı bilgi vermek;\n• Özellikleri kötüye kullanmak amacıyla birden fazla hesap açmak;\n• Hesabını başkasına satmak, devretmek, kiralamak veya vermek;\n• Başka bir kullanıcının hesabına erişmeye çalışmak;\n• Başkasının kimlik doğrulama bilgilerini izinsiz kullanmak.\nHesabına izinsiz erişildiğine inanıyorsan bizi bilgilendirmelisin." },
    { t: "4. Swipedia Deneyimi", b: "Swipedia sürekli göz atılabilen bir soru deneyimi sunar. Sorular tek tek veya gruplar hâlinde, kaydırma tabanlı bir arayüz üzerinden gösterilebilir. Özelliğe bağlı olarak kullanıcılar bir sonraki soruya kaydırabilir, yanıt seçebilir, soru atlayabilir, soruları kaydedebilir veya sorularla etkileşime geçebilir, doğru ya da yanlış yanıtları görebilir, puan veya istatistik alabilir, ilerlemesini görüntüleyebilir, kişiselleştirilmiş öneriler alabilir ya da sıralamalara, mücadelelere ve benzeri özelliklere katılabilir. Kullanılabilir özellikler ülkeye, platforma, hesap türüne, cihaza, dile veya uygulama sürümüne göre değişebilir." },
    { t: "5. Sorular ve Eğitici İçerik", b: "Swipedia; genel kültür, bilim, tarih, coğrafya, matematik, dil, edebiyat, teknoloji, spor, eğlence, doğa, astronomi, kültür, oyunlar ve diğer eğitici veya bilgilendirici konular dâhil ancak bunlarla sınırlı olmamak üzere sorular içerebilir. Swipedia yararlı ve doğru bilgi sunmaya çalışır. Ancak sorular ve yanıtlar zaman zaman hata, eksiklik, güncelliğini yitirmiş bilgi, belirsizlik veya yorum farkları içerebilir. Açıkça aksi belirtilmedikçe Swipedia; her sorunun, yanıtın, açıklamanın, istatistiğin veya bilgi ifadesinin eksiksiz, güncel ya da hatasız olduğunu garanti etmez. Swipedia üzerinden sunulan içerik; profesyonel tıbbi, hukuki, finansal, bilimsel veya diğer uzmanlık gerektiren tavsiye olarak değerlendirilmemelidir." },
    { t: "6. Yanıtlar, Puanlar ve Sonuçlar", b: "Bazı özellikler yanıtlarını ve etkileşimlerini kaydedebilir. Özelliğe bağlı olarak Hizmet; puan, doğruluk yüzdesi, seri, ilerleme, ilgi kategorileri, sıralama, başarım, rozet, istatistik veya diğer performans göstergelerini hesaplayabilir. Bu sonuçlar öncelikle eğlence, eğitim ve bilgilendirme amaçlıdır. Hizmet geliştikçe veya veriler düzeltildikçe puanlar ve sıralamalar değişebilir. Swipedia; puanların, sıralamaların, istatistiklerin veya başarımların her zaman erişilebilir ya da korunacak olduğunu garanti etmez." },
    { t: "7. Kişiselleştirme ve Öneriler", b: "Swipedia, sana sunulan soruları iyileştirmek için etkileşimlerinle ilgili bilgileri kullanabilir. Örneğin Hizmet; görüntülediğin soruları, yanıtladığın soruları, seçtiğin yanıtları, etkileşime geçtiğin kategorileri, atladığın soruları, dil tercihlerini, genel kullanım alışkanlıklarını, seçtiğin ilgi alanlarını ve izin verilen diğer bilgileri dikkate alabilir. Kişiselleştirmenin amacı deneyimini düzenlemek ve iyileştirmek, ilgi alanlarına uygun olabilecek sorular sunmaktır. Kişiselleştirme, her önerinin tercihlerine göre mutlaka doğru veya uygun olacağı anlamına gelmez." },
    { t: "8. Kabul Edilebilir Kullanım", b: "Swipedia'yı yalnızca yasal amaçlarla ve bu Koşullar'a uygun olarak kullanmayı kabul edersin. Şunları yapmamalısın:\n• Swipedia'yı yasa dışı amaçlarla kullanmak;\n• Hizmet'e müdahale etmek veya aksatmak;\n• Yasanın izin verdiği durumlar dışında tersine mühendislik yapmak, kaynak kodu elde etmeye çalışmak;\n• Güvenlik veya kimlik doğrulama sistemlerini atlatmak;\n• İzinsiz olarak bot, betik, tarayıcı veya veri kazıma araçları kullanmak;\n• Puanları, sıralamaları, istatistikleri veya diğer özellikleri manipüle etmek;\n• Hataları veya açıkları istismar etmek;\n• Veri tabanlarına, sunuculara, hesaplara veya sistemlere izinsiz erişmek;\n• Zararlı kod, kötü amaçlı yazılım veya virüs yaymak;\n• Raporlama veya moderasyon sistemlerini kötüye kullanmak;\n• Başka bir kişi veya kurumun kimliğine bürünmek;\n• Başkasının haklarını ihlal etmek;\n• Diğer kullanıcılar hakkında izinsiz bilgi toplamak;\n• Teknik sınırlamaları aşmak;\n• Hizmet'e zarar vermek, aşırı yüklemek veya işleyişini bozmak;\n• Başkasını bu Koşullar'ı ihlale teşvik etmek veya yardım etmek." },
    { t: "9. Fikri Mülkiyet", b: "Aksi belirtilmedikçe Swipedia ve lisans verenleri; Swipedia adı ve logosu, yazılım, kullanıcı arayüzü tasarımları, grafikler, görsel ögeler, metinler, soru veri tabanları, açıklamalar, algoritmalar, veri tabanı yapıları, marka, web sitesi içeriği, uygulama mimarisi ve Swipedia tarafından sağlanan diğer materyaller dâhil olmak üzere Hizmet'e ilişkin tüm fikri mülkiyet haklarına sahiptir veya bunları kontrol eder. Hizmet'i yalnızca amacına uygun kullanabilirsin. Bu Koşullar sana Swipedia'nın fikri mülkiyetinin sahipliğini vermez. Yasanın izin verdiği durumlar dışında, önceden yazılı izin almadan Swipedia'nın tescilli materyallerini çoğaltamaz, dağıtamaz, değiştiremez, satamaz, kamuya açık biçimde sergileyemez, ticari olarak kullanamaz veya bunlardan türev çalışmalar oluşturamazsın." },
    { t: "10. Soru Veri Tabanı ve İçerik Koruması", b: "Swipedia içindeki soruların toplanması, düzenlenmesi, organizasyonu, seçimi ve sunumu Swipedia'ya veya lisans verenlerine ait tescilli materyal oluşturabilir. Sorularla uygulamanın normal işlevselliği üzerinden etkileşime geçebilirsin. Swipedia'nın soru veri tabanının önemli bir bölümünü izinsiz olarak sistematik biçimde kopyalayamaz, çıkaramaz, kazıyamaz, yeniden üretemez, yeniden yayımlayamaz, satamaz veya dağıtamazsın. Bu kısıtlama, geçerli hukuk kapsamında yasal olarak kısıtlanamayacak hakları sınırlamaz." },
    { t: "11. Üçüncü Taraf Hizmetleri", b: "Swipedia; kimlik doğrulama, bulut altyapısı, analiz, çökme raporlama, bildirimler, reklamcılık, ödemeler, müşteri desteği, güvenlik, veri depolama ve diğer teknik hizmetler gibi işlevler için üçüncü taraf hizmetlerine dayanabilir. Üçüncü taraf hizmetlerinin kendi koşulları ve gizlilik politikaları olabilir. Swipedia, üçüncü taraf hizmetlerinin bağımsız politikalarından veya uygulamalarından sorumlu değildir. Bu nedenle üçüncü taraf hizmetlerini kullanımın ek sözleşmelere tabi olabilir." },
    { t: "12. Reklamcılık", b: "Swipedia'ya reklam eklenirse, reklamlar Swipedia veya üçüncü taraf reklam sağlayıcıları tarafından sunulabilir. Reklamlar, geçerli hukukun ve gizlilik tercihlerinin izin verdiği bilgilere göre seçilebilir veya iletilebilir. Gerektiğinde Swipedia; belirli kişiselleştirilmiş reklam biçimleri için onay, itiraz veya vazgeçme mekanizmaları sağlayacaktır. Swipedia, reklam verenlerin ürün, hizmet veya iddialarını onaylamak zorunda değildir." },
    { t: "13. Ücretli Özellikler", b: "Swipedia; ücretli özellikler, abonelikler, premium hesaplar veya uygulama içi satın alımlar sunabilir. Ücretli özellikler sunulduğunda geçerli fiyatlandırma, faturalandırma koşulları, yenileme şartları, iptal yöntemleri ve iade politikaları satın alma öncesinde gösterilecektir. Apple App Store, Google Play veya başka bir platform üzerinden yapılan satın alımlar ayrıca o platformun koşullarına tabi olabilir. Abonelikler, geçerli ve izin verilen durumlarda otomatik olarak yenilenebilir. Satın alma anında gösterilen bilgileri gözden geçirmek kullanıcının sorumluluğundadır." },
    { t: "14. Kullanıcı Geri Bildirimi", b: "Swipedia'yla ilgili öneri, fikir, tavsiye, hata raporu veya başka geri bildirim (\"Geri Bildirim\") sunarsan, Swipedia'ya bu Geri Bildirim'i Hizmet'i iyileştirmek, geliştirmek ve işletmek dâhil amaçlarla kullanma hakkını verirsin. Yazılı olarak aksi kararlaştırılmadıkça Geri Bildirim bir bedel ödenmeden kullanılabilir. Genel geri bildirim kanallarından gizli bilgi göndermemelisin." },
    { t: "15. Hizmetin Erişilebilirliği", b: "Swipedia'yı erişilebilir ve işlevsel tutmaya çalışırız, ancak kesintisiz erişim garanti etmeyiz. Hizmet; bakım, güncelleme, teknik arıza, güvenlik olayları, ağ sorunları, üçüncü taraf hizmet arızaları, sunucu sorunları, yasal gereklilikler, mücbir sebepler veya makul kontrolümüz dışındaki diğer durumlar nedeniyle zaman zaman kullanılamayabilir. Swipedia'nın herhangi bir bölümünü istediğimiz zaman değiştirebilir, askıya alabilir, kısıtlayabilir veya durdurabiliriz." },
    { t: "16. Güncellemeler", b: "Swipedia; özellikleri değiştiren, iyileştiren, ekleyen veya kaldıran güncellemeler yayımlayabilir. Belirli özellikleri kullanmaya devam etmek için güncellemeleri yüklemen gerekebilir. Bazı eski sürümler zamanla desteklenmeyebilir." },
    { t: "17. Hesabın Askıya Alınması ve Kapatılması", b: "Bu Koşullar'ı veya geçerli yasayı ihlal etmen, Hizmet'i kötüye kullanman, manipüle etmeye çalışman, Swipedia'nın veya diğer kullanıcıların güvenliğini tehlikeye atman, önemli ölçüde yanlış bilgi vermen ya da erişimin sürmesinin yasal, güvenlik veya operasyonel bir risk oluşturduğuna makul şekilde inanmamız durumunda hesabını askıya alabilir veya kapatabiliriz. Uygun ve yasal olarak gerekli olduğunda, kapatmadan önce bildirimde bulunabilir veya sorunu giderme imkânı tanıyabiliriz. Swipedia'yı istediğin zaman kullanmayı bırakabilirsin. Hesap silme, uygulama üzerinden veya bizimle iletişime geçerek yapılabilir. Silme işlemi, yasanın saklamayı gerektirdiği veya izin verdiği durumlarda her bilginin hemen silinebileceği anlamına gelmez." },
    { t: "18. Sorumluluk Reddi", b: "Geçerli hukukun izin verdiği azami ölçüde Swipedia \"olduğu gibi\" ve \"mevcut olduğu şekliyle\" sunulur. Hizmet'in her zaman erişilebilir olacağını, tamamen hatasız olacağını, her sorunun olgusal olarak kusursuz olacağını, her yanıtın her kullanıcı için uygun olacağını, her beklentiyi karşılayacağını, puan veya istatistiklerin her zaman doğru olacağını ya da Hizmet'in kesintisiz çalışacağını garanti etmeyiz. Bu Koşullar'daki hiçbir hüküm, yasal olarak hariç tutulamayacak tüketici haklarını veya korumalarını ortadan kaldırmaz." },
    { t: "19. Sorumluluğun Sınırlandırılması", b: "Geçerli hukukun izin verdiği azami ölçüde Swipedia ve yöneticileri, çalışanları, yüklenicileri, bağlı kuruluşları ve hizmet sağlayıcıları; Hizmet'i kullanımından doğan veya bununla ilgili dolaylı, arızi, özel, sonuç niteliğinde veya cezai zararlardan sorumlu olmayacaktır. Sorumluluğun yasal olarak hariç tutulamadığı durumlarda, geçerli hukukun izin verdiği azami ölçüde sınırlı olacaktır." },
    { t: "20. Tazminat", b: "Geçerli hukukun izin verdiği ölçüde; bu Koşullar'ı ihlal etmenden, Hizmet'i yasa dışı kullanmandan, başkasının haklarını ihlal etmenden veya Hizmet'i kötüye kullanmandan doğan talep, kayıp, yükümlülük, zarar, masraf ve giderlere karşı Swipedia ve yöneticileri, çalışanları, bağlı kuruluşları, yüklenicileri ve hizmet sağlayıcılarını tazmin etmeyi ve zarardan korumayı kabul edersin. Bu hüküm yalnızca geçerli hukukun izin verdiği ölçüde uygulanır." },
    { t: "21. Gizlilik", b: "Swipedia'yı kullanımın aynı zamanda Gizlilik Politikamıza tabidir; bu politika kişisel bilgileri nasıl topladığımızı, kullandığımızı, sakladığımızı, açıkladığımızı ve koruduğumuzu açıklar. Swipedia'yı kullanarak Gizlilik Politikası'nı incelediğini kabul edersin. Bu Koşullar'daki hiçbir hüküm, geçerli gizlilik yasaları kapsamında sana tanınan hakların yerine geçmez." },
    { t: "22. Uluslararası Kullanım", b: "Swipedia dünya genelindeki ülkelerden erişilebilir olabilir. Swipedia'ya veya hizmet sağlayıcılarının bulunduğu ülke dışından erişirsen, kullanımına uygulanan yasalara uymaktan sen sorumlusun. Kişisel bilgilerin, geçerli gizlilik yasalarına ve gerektiğinde uygun güvencelere tabi olarak ikamet ettiğin ülke dışındaki ülkelerde işlenebilir." },
    { t: "23. Uygulanacak Hukuk", b: "Bu Koşullar; ülkende geçerli zorunlu tüketici koruma yasalarının aksini öngördüğü ölçüde hariç olmak üzere, Türkiye yasalarına tabi olacaktır. Bu bölümdeki hiçbir hüküm, tüketicilerin kendilerine uygulanan yasalarca tanınan zorunlu hak ve korumalara dayanmasını engellemez." },
    { t: "24. Uyuşmazlık Çözümü", b: `Resmî hukuki süreç başlatmadan önce, sorunu gayriresmî olarak çözmeye çalışabilmemiz için bizimle iletişime geçmeni öneririz. Bize şu adresten ulaşabilirsin: ${CONTACT_EMAIL}. Bir uyuşmazlık gayriresmî olarak çözülemezse, uygulanacak hukuk ve zorunlu tüketici koruma yasaları kapsamında mahkemeler veya uyuşmazlık çözüm mekanizmaları yoluyla çözülebilir. Uygun olduğunda, belirli yargı bölgelerindeki tüketiciler alternatif uyuşmazlık çözüm mekanizmalarına veya yerel mahkemelere erişebilir.` },
    { t: "25. Bu Koşullardaki Değişiklikler", b: "Bu Koşullar'ı zaman zaman güncelleyebiliriz. Önemli değişiklikler yaptığımızda uygulama, web sitesi, e-posta veya başka uygun bir yöntemle bildirimde bulunabiliriz. Güncellenen Koşullar, güncel sürümde belirtilen tarihte yürürlüğe girer. Yürürlük tarihinden sonra Swipedia'yı kullanmaya devam etmen, geçerli hukukun izin verdiği ölçüde güncellenen Koşullar'ı kabul ettiğin anlamına gelir." },
    { t: "26. Bölünebilirlik", b: "Bu Koşullar'ın herhangi bir hükmünün geçersiz veya uygulanamaz olduğu belirlenirse, kalan hükümler yasanın izin verdiği ölçüde geçerliliğini sürdürür." },
    { t: "27. Bütün Sözleşme", b: "Bu Koşullar; Gizlilik Politikası ve belirli özellikler için sunulan ek koşullarla birlikte, Hizmet'i kullanımına ilişkin olarak seninle Swipedia arasındaki sözleşmeyi oluşturur." },
    { t: "28. İletişim", b: `Bu Koşullar hakkında sorun varsa lütfen bize ulaş:\nSwipedia\nE-posta: ${CONTACT_EMAIL}\nTelefon: ${PHONE}\nWeb sitesi: ${WEBSITE}` },
  ],
};

const PRIVACY_EN: LegalDoc = {
  title: "Swipedia Privacy Policy",
  updated: "Last Updated: 02.10.2026",
  sections: [
    { t: "1. Overview", b: "Swipedia respects your privacy. This Privacy Policy explains how we collect, use, disclose, store, protect, and otherwise process information when you use the Swipedia mobile application, website, and related services (collectively, the \"Service\"). Swipedia is a global question-based discovery platform. Instead of primarily displaying photographs or videos, Swipedia allows users to discover questions through a swipe-based interface and interact with educational, informational, trivia, and knowledge-based content. By using Swipedia, you acknowledge the practices described in this Privacy Policy." },
    { t: "2. Information We May Collect", b: "The information we collect depends on how you use Swipedia and which features you use.\n\nAccount Information: If you create an account, we may collect your username, display name, email address, account identifier, authentication information, profile information you choose to provide, and information associated with third-party login providers. We only collect information necessary for the relevant account functionality.\n\nLogin Information: If Swipedia supports third-party authentication such as Google Sign-In or Apple Sign-In, we may receive information made available by the provider, which may include a unique account identifier, name, email address, and other information you authorize the provider to share. Swipedia does not receive your third-party account password." },
    { t: "3. Your Swipedia Activity", b: "Because Swipedia is based on an interactive swipe experience, we may collect information about how you interact with questions. This may include questions displayed to you, questions opened, questions skipped, questions swiped away, answers selected, correct or incorrect answers, categories viewed, time spent interacting with certain features, session information, progress, scores, streaks, achievements, saved questions where available, preferences, and other interactions with Swipedia features. This information may be used to operate the Service and improve the question experience." },
    { t: "4. Personalization", b: "Swipedia may use interaction information to personalize the questions presented to you. For example, the Service may use information about categories you frequently interact with, questions you answer, questions you skip, your language preference, your general usage patterns, and your previous activity within the Service. The purpose of personalization is to improve discovery and make the question feed more relevant. Where applicable law grants you rights relating to profiling or automated decision-making, you may exercise those rights as described in this Privacy Policy." },
    { t: "5. Device and Technical Information", b: "When you use Swipedia, certain technical information may be automatically collected, including device type, operating system and version, application version, language, time zone, IP address, general device identifiers, advertising identifiers where permitted, network information, crash information, performance information, and technical diagnostic information. We may use this information to operate the Service, maintain security, diagnose technical problems, prevent abuse, improve performance, understand general usage, detect crashes, and improve the application." },
    { t: "6. Log Information", b: "Our systems may automatically create technical logs when you use Swipedia, including IP address, date and time of access, application version, device information, error information, screens accessed, actions performed within the Service, and technical events. Log information may be used for security, troubleshooting, analytics, fraud prevention, and service improvement." },
    { t: "7. Cookies and Similar Technologies", b: "If Swipedia uses cookies, SDKs, local storage, pixels, device identifiers, or similar technologies, we may use them for authentication, maintaining sessions, security, preferences, analytics, performance, advertising, and personalization. Where applicable law requires consent for certain technologies, we will seek the required consent before using them. You may also control certain technologies through your device or browser settings." },
    { t: "8. Location Information", b: "Swipedia does not necessarily require precise location information to provide its core question-based experience. If we introduce location-based features, we will explain the relevant collection and use of location information and request permissions where required. Unless specifically stated otherwise, you should not assume that Swipedia continuously tracks your precise physical location." },
    { t: "9. Camera, Microphone, Photos, and Videos", b: "Swipedia's core experience is based on questions rather than user-uploaded photographs or videos. Unless a particular feature specifically requires them, Swipedia does not need access to your camera, microphone, photo library, or video library. If these permissions are introduced for a future feature, the applicable permission and privacy information will be updated accordingly." },
    { t: "10. How We Use Information", b: "We may use information to provide the Service (create and maintain accounts, provide questions, record answers, maintain progress, provide scores and personalization, deliver requested features, and provide customer support); to improve Swipedia (understand usage, improve discovery and the interface, develop features, analyze performance, fix bugs, improve reliability); for security and abuse prevention (detect suspicious activity, prevent fraud and manipulation, protect accounts and infrastructure, investigate abuse, enforce our Terms); and for communications (account-related messages, security notices, service announcements, important changes, support responses). Marketing communications will be handled in accordance with applicable law and available user choices." },
    { t: "11. Legal Bases for Processing", b: "Where GDPR or similar laws apply, we may process personal information under one or more legal bases: performance of a contract (to provide the Service you requested), legitimate interests (such as security, fraud prevention, service improvement, technical diagnostics, abuse prevention, and protecting our systems, provided those interests are not overridden by your rights), consent (which you may withdraw where legally permitted, without affecting prior lawful processing), and legal obligations." },
    { t: "12. How Long We Keep Information", b: "We retain personal information only for as long as reasonably necessary for the purposes described in this Privacy Policy, unless a longer period is required or permitted by law. Retention periods may depend on the type of information, why it was collected, whether your account remains active, legal and security requirements, dispute resolution, and legitimate business needs. When information is no longer required, we may delete, anonymize, or securely dispose of it. Some information may remain in backups for a limited period before being securely overwritten." },
    { t: "13. Information Sharing", b: "We do not share personal information indiscriminately. We may share information with categories of recipients where necessary to operate Swipedia, comply with law, or perform legitimate business functions. These categories may include cloud hosting providers, database providers, authentication providers, analytics providers, crash reporting providers, security providers, customer support providers, payment providers, advertising providers where applicable, communication providers, professional advisors, government authorities where legally required, and corporate transaction counterparties where legally permitted. Third-party providers may process information on our behalf and may be subject to contractual and legal obligations." },
    { t: "14. Third-Party Service Providers", b: "Swipedia may use third-party technology providers for authentication, cloud hosting, databases, analytics, crash reporting, push notifications, advertising, payments, email, security, and customer support. A current list of third-party providers may be made available through the application or website where appropriate. You should not interpret this Privacy Policy as stating that Swipedia uses every provider listed in any example or template; only providers actually used by Swipedia apply." },
    { t: "15. Advertising", b: "If Swipedia displays advertising, we may use third-party advertising providers who may receive certain information necessary to deliver and measure advertisements, subject to applicable law and your choices. Depending on the jurisdiction and technology, this may include device information, advertising identifiers, approximate location derived from technical information, interaction information, and advertising-related events. Where required, we will obtain consent before using information for personalized advertising. Users may have additional rights to opt out of the sale or sharing of personal information under certain applicable laws." },
    { t: "16. Analytics", b: "We may use analytics technologies to understand which features are used, which categories are popular, how the application performs, where crashes occur, how users navigate the application, and how we can improve the Service. Analytics providers may process technical and usage information according to their own terms and applicable agreements with Swipedia." },
    { t: "17. International Data Transfers", b: "Because Swipedia is intended to be a global service, information may be processed or stored in countries other than the country where you live. Where applicable law requires safeguards for international transfers, we will use appropriate legal mechanisms. For users in the European Economic Area, the United Kingdom, or other jurisdictions with comparable requirements, these may include applicable adequacy decisions, contractual safeguards, or other lawful transfer mechanisms." },
    { t: "18. GDPR Rights", b: `If the GDPR applies to you, you may have the right to be informed; to access your personal information; to correct inaccurate information; to request deletion; to restrict processing; to data portability; to object to certain processing; to withdraw consent where processing is based on consent; and rights relating to certain automated decision-making and profiling. These rights are subject to applicable legal exceptions. To exercise your rights, contact: ${CONTACT_EMAIL}. We may need to verify your identity before completing certain requests.` },
    { t: "19. California Privacy Rights", b: `If you are a California resident and applicable California privacy law applies, you may have the right to know what personal information is collected, how it is used and shared; to request deletion or correction; to opt out of certain sales or sharing of personal information; to limit certain uses of sensitive personal information where applicable; and not to receive discriminatory treatment for exercising applicable privacy rights. The exact availability depends on applicable law. Requests may be submitted via Email: ${CONTACT_EMAIL} or our Privacy Request Page: ${WEBSITE}.` },
    { t: "20. \"Do Not Sell or Share\" and Global Privacy Control", b: "Where applicable law requires an opt-out mechanism for the sale or sharing of personal information, Swipedia will provide the applicable mechanism. Where legally required and technically supported, we may recognize applicable browser or device privacy signals such as Global Privacy Control. The availability and scope of such mechanisms may depend on the jurisdiction and the technologies used by Swipedia." },
    { t: "21. Turkish Users and KVKK", b: `If the Turkish Personal Data Protection Law No. 6698 (\"KVKK\") applies to you, Swipedia will process personal data in accordance with applicable requirements. Under KVKK, individuals have rights concerning their personal data, including learning whether their data is processed, requesting information about processing, learning the purposes and recipients of processing, requesting correction, deletion or destruction where applicable, and other rights provided under the law. Swipedia will provide the legally required information regarding the identity of the data controller, the purposes of processing, the persons or categories to whom data may be transferred, the method and legal basis of collection, and applicable data-subject rights. Requests may be sent to: ${CONTACT_EMAIL}.` },
    { t: "22. Children's Privacy", b: `Swipedia is not intended to knowingly collect personal information from children in violation of applicable law. Age requirements may vary by country. If we learn that we have collected personal information from a child where such collection was not permitted, we may take appropriate steps to delete it. Parents or legal guardians who believe that a child has provided personal information may contact us at: ${CONTACT_EMAIL}.` },
    { t: "23. Data Security", b: "We use reasonable technical and organizational measures designed to protect personal information against unauthorized access, loss, misuse, alteration, or disclosure, including encryption in transit, access controls, authentication mechanisms, monitoring, security testing, infrastructure protections, and other appropriate safeguards. However, no internet transmission or storage system can be guaranteed to be completely secure, so we cannot guarantee absolute security." },
    { t: "24. Data Breaches", b: "If a security incident occurs that affects personal information, we will take steps required by applicable law. Depending on the nature and severity of the incident, this may include investigating and containing the incident, implementing security measures, and notifying affected individuals or authorities where legally required." },
    { t: "25. Your Account and Data Deletion", b: `You may request deletion of your Swipedia account and associated personal information where applicable. You may submit a request through ${WEBSITE} or ${CONTACT_EMAIL}. Certain information may need to be retained where required or permitted by law, including information necessary for legal compliance, security, fraud prevention, dispute resolution, or enforcement of legal rights. Where deletion is not immediately possible because information is stored in backups, such information will be handled according to applicable retention and security procedures.` },
    { t: "26. Data Access and Correction", b: `If you believe information associated with your account is inaccurate or incomplete, you may request correction. Depending on the feature, you may also be able to modify certain information directly within the application. Requests can be submitted to: ${CONTACT_EMAIL}.` },
    { t: "27. Marketing Communications", b: "Where permitted by applicable law, Swipedia may send promotional communications. You may unsubscribe using the unsubscribe mechanism included in the communication or through available account settings. Even if you opt out of marketing communications, we may continue sending essential service-related messages, such as security notices, account notifications, or important legal updates." },
    { t: "28. Automated Decision-Making and Profiling", b: "Swipedia may use automated systems to organize, rank, or recommend questions. For example, the system may use your previous interactions to determine which questions or categories may be shown to you. These systems are intended to improve content discovery and personalization. Unless otherwise stated, Swipedia does not intend for these systems to make decisions that produce legal or similarly significant effects on users. Where applicable law provides specific rights concerning automated decision-making or profiling, those rights remain available." },
    { t: "29. User-Generated Information", b: "If Swipedia introduces features allowing users to submit information, questions, comments, profiles, feedback, or other content, such information may be processed as necessary to provide those features. Users should avoid submitting sensitive personal information unless the relevant feature specifically requires it and appropriate safeguards are provided." },
    { t: "30. Public Information", b: "If Swipedia introduces public profiles, leaderboards, rankings, achievements, or other public features, certain information may become visible to other users depending on the feature and your settings. Before making information publicly visible, Swipedia will provide appropriate information or controls where required." },
    { t: "31. Legal Disclosures", b: "We may disclose information where reasonably necessary to comply with legal obligations, respond to lawful requests, protect the rights or safety of users, protect Swipedia, investigate fraud or abuse, enforce our Terms, or respond to legal proceedings. We may also disclose information in connection with a merger, acquisition, financing, restructuring, sale of assets, or similar corporate transaction, subject to applicable law." },
    { t: "32. Third-Party Links", b: "Swipedia may contain links to third-party websites or services. We are not responsible for the privacy practices of third-party websites. We recommend reviewing the privacy policies of third-party services before providing personal information." },
    { t: "33. Data Retention After Account Deletion", b: "When an account is deleted, we will process associated information according to our applicable retention procedures. Some information may remain for a limited period because of legal obligations, fraud prevention, security, accounting, dispute resolution, enforcement of agreements, or backup systems. Where retention is required, information will not be retained longer than necessary for the applicable purpose unless otherwise permitted by law." },
    { t: "34. Changes to This Privacy Policy", b: "We may update this Privacy Policy from time to time. If we make material changes, we may notify users through the application, our website, email, an in-app notification, or another appropriate method. The \"Last Updated\" date at the top indicates when the policy was most recently revised." },
    { t: "35. Contact Us", b: `If you have questions about this Privacy Policy or your personal information, contact us:\nSwipedia Privacy Email: ${CONTACT_EMAIL}\nGeneral Contact: ${GENERAL_EMAIL}\nWebsite: ${WEBSITE}` },
    { t: "36. Data Protection Authority Complaints", b: "Depending on your location, you may have the right to lodge a complaint with your local data protection authority. For users in the European Economic Area, the relevant supervisory authority may be the data protection authority in the country where you live, work, or where you believe an infringement occurred. This right does not prevent you from first contacting Swipedia regarding your concern." },
    { t: "37. Final Notice", b: "This Privacy Policy describes Swipedia's intended privacy practices based on the features and technologies actually used by the Service. If Swipedia introduces new features that materially change how personal information is collected or used, this Privacy Policy may be updated accordingly." },
  ],
};

const PRIVACY_TR: LegalDoc = {
  title: "Swipedia Gizlilik Politikası",
  updated: "Son Güncelleme: 02.10.2026",
  sections: [
    { t: "1. Genel Bakış", b: "Swipedia gizliliğine saygı duyar. Bu Gizlilik Politikası; Swipedia mobil uygulamasını, web sitesini ve ilgili hizmetleri (topluca \"Hizmet\") kullandığında bilgileri nasıl topladığımızı, kullandığımızı, açıkladığımızı, sakladığımızı, koruduğumuzu ve başka şekilde işlediğimizi açıklar. Swipedia, soru temelli küresel bir keşif platformudur. Öncelikle fotoğraf veya video göstermek yerine Swipedia; kullanıcıların kaydırma tabanlı bir arayüz üzerinden soruları keşfetmesine ve eğitici, bilgilendirici, bilgi yarışması ve bilgi temelli içeriklerle etkileşime geçmesine olanak tanır. Swipedia'yı kullanarak bu Gizlilik Politikası'nda açıklanan uygulamaları kabul etmiş olursun." },
    { t: "2. Toplayabileceğimiz Bilgiler", b: "Topladığımız bilgiler, Swipedia'yı nasıl kullandığına ve hangi özellikleri kullandığına bağlıdır.\n\nHesap Bilgileri: Hesap oluşturursan kullanıcı adını, görünen adını, e-posta adresini, hesap tanımlayıcını, kimlik doğrulama bilgilerini, sağlamayı seçtiğin profil bilgilerini ve üçüncü taraf giriş sağlayıcılarıyla ilişkili bilgileri toplayabiliriz. Yalnızca ilgili hesap işlevi için gerekli bilgileri toplarız.\n\nGiriş Bilgileri: Swipedia; Google ile Giriş veya Apple ile Giriş gibi üçüncü taraf kimlik doğrulamayı desteklerse, sağlayıcının sunduğu bilgileri alabiliriz; bu bilgiler benzersiz bir hesap tanımlayıcısı, ad, e-posta adresi ve sağlayıcının paylaşmasına izin verdiğin diğer bilgileri içerebilir. Swipedia, üçüncü taraf hesap şifreni almaz." },
    { t: "3. Swipedia Etkinliğin", b: "Swipedia etkileşimli bir kaydırma deneyimine dayandığından, sorularla nasıl etkileşime geçtiğine dair bilgi toplayabiliriz. Bu; sana gösterilen sorular, açılan sorular, atlanan sorular, kaydırılarak geçilen sorular, seçilen yanıtlar, doğru veya yanlış yanıtlar, görüntülenen kategoriler, belirli özelliklerle geçirilen süre, oturum bilgileri, ilerleme, puanlar, seriler, başarımlar, varsa kaydedilen sorular, tercihler ve Swipedia özellikleriyle diğer etkileşimleri içerebilir. Bu bilgiler Hizmet'i işletmek ve soru deneyimini iyileştirmek için kullanılabilir." },
    { t: "4. Kişiselleştirme", b: "Swipedia, sana sunulan soruları kişiselleştirmek için etkileşim bilgilerini kullanabilir. Örneğin Hizmet; sıkça etkileşime geçtiğin kategorileri, yanıtladığın soruları, atladığın soruları, dil tercihini, genel kullanım alışkanlıklarını ve Hizmet içindeki önceki etkinliğini kullanabilir. Kişiselleştirmenin amacı keşfi iyileştirmek ve soru akışını daha alakalı hâle getirmektir. Geçerli hukuk; profilleme veya otomatik karar vermeyle ilgili haklar tanıyorsa, bu hakları bu Gizlilik Politikası'nda açıklandığı şekilde kullanabilirsin." },
    { t: "5. Cihaz ve Teknik Bilgiler", b: "Swipedia'yı kullandığında; cihaz türü, işletim sistemi ve sürümü, uygulama sürümü, dil, saat dilimi, IP adresi, genel cihaz tanımlayıcıları, izin verildiğinde reklam tanımlayıcıları, ağ bilgileri, çökme bilgileri, performans bilgileri ve teknik tanılama bilgileri gibi bazı teknik bilgiler otomatik olarak toplanabilir. Bu bilgileri Hizmet'i işletmek, güvenliği korumak, teknik sorunları teşhis etmek, kötüye kullanımı önlemek, performansı iyileştirmek, genel kullanımı anlamak, çökmeleri tespit etmek ve uygulamayı geliştirmek için kullanabiliriz." },
    { t: "6. Günlük (Log) Bilgileri", b: "Sistemlerimiz, Swipedia'yı kullandığında IP adresi, erişim tarih ve saati, uygulama sürümü, cihaz bilgileri, hata bilgileri, erişilen ekranlar, Hizmet içinde gerçekleştirilen işlemler ve teknik olaylar gibi teknik günlükleri otomatik olarak oluşturabilir. Günlük bilgileri güvenlik, sorun giderme, analiz, dolandırıcılık önleme ve hizmet iyileştirme için kullanılabilir." },
    { t: "7. Çerezler ve Benzer Teknolojiler", b: "Swipedia; çerezler, SDK'ler, yerel depolama, pikseller, cihaz tanımlayıcıları veya benzer teknolojiler kullanırsa bunları kimlik doğrulama, oturum sürdürme, güvenlik, tercihler, analiz, performans, reklamcılık ve kişiselleştirme için kullanabiliriz. Geçerli hukuk belirli teknolojiler için onay gerektirdiğinde, kullanmadan önce gerekli onayı alırız. Ayrıca bazı teknolojileri cihaz veya tarayıcı ayarlarından kontrol edebilirsin." },
    { t: "8. Konum Bilgileri", b: "Swipedia, temel soru deneyimini sunmak için kesin konum bilgisi gerektirmez. Konum tabanlı özellikler eklersek, konum bilgisinin ilgili toplanmasını ve kullanımını açıklar ve gerektiğinde izin isteriz. Açıkça aksi belirtilmedikçe Swipedia'nın kesin fiziksel konumunu sürekli takip ettiğini varsaymamalısın." },
    { t: "9. Kamera, Mikrofon, Fotoğraflar ve Videolar", b: "Swipedia'nın temel deneyimi, kullanıcıların yüklediği fotoğraf veya videolar yerine sorulara dayanır. Belirli bir özellik bunları özellikle gerektirmedikçe Swipedia; kameraya, mikrofona, fotoğraf veya video kitaplığına erişime ihtiyaç duymaz. Bu izinler gelecekteki bir özellik için eklenirse, ilgili izin ve gizlilik bilgileri buna göre güncellenecektir." },
    { t: "10. Bilgileri Nasıl Kullanırız", b: "Bilgileri; Hizmet'i sunmak (hesap oluşturma ve sürdürme, soru sunma, yanıtları kaydetme, ilerlemeyi sürdürme, puan ve kişiselleştirme sağlama, istenen özellikleri sunma ve müşteri desteği verme); Swipedia'yı iyileştirmek (kullanımı anlama, keşfi ve arayüzü iyileştirme, özellik geliştirme, performans analizi, hata giderme, güvenilirliği artırma); güvenlik ve kötüye kullanım önleme (şüpheli etkinlikleri tespit etme, dolandırıcılık ve manipülasyonu önleme, hesapları ve altyapıyı koruma, kötüye kullanımı araştırma, Koşullar'ı uygulama); ve iletişim (hesapla ilgili mesajlar, güvenlik bildirimleri, hizmet duyuruları, önemli değişiklikler, destek yanıtları) için kullanabiliriz. Pazarlama iletişimleri geçerli hukuka ve kullanıcı tercihlerine uygun olarak ele alınacaktır." },
    { t: "11. İşlemenin Hukuki Dayanakları", b: "GDPR veya benzer yasalar geçerli olduğunda kişisel bilgileri bir veya daha fazla hukuki dayanakla işleyebiliriz: sözleşmenin ifası (istediğin Hizmet'i sunmak için), meşru menfaatler (güvenlik, dolandırıcılık önleme, hizmet iyileştirme, teknik tanılama, kötüye kullanım önleme ve sistemlerimizi koruma gibi; bu menfaatler haklarının üstünde olmadığı sürece), onay (yasal olarak izin verildiğinde geri çekebilirsin; geri çekme öncesindeki işlemenin hukuka uygunluğunu etkilemez) ve yasal yükümlülükler." },
    { t: "12. Bilgileri Ne Kadar Saklarız", b: "Kişisel bilgileri yalnızca bu Gizlilik Politikası'nda açıklanan amaçlar için makul olarak gerekli olduğu sürece saklarız; yasa daha uzun bir süre gerektirmedikçe veya izin vermedikçe. Saklama süreleri; bilginin türüne, neden toplandığına, hesabının etkin olup olmadığına, yasal ve güvenlik gerekliliklerine, uyuşmazlık çözümüne ve meşru iş ihtiyaçlarına bağlı olabilir. Bilgi artık gerekli olmadığında silebilir, anonimleştirebilir veya güvenli şekilde imha edebiliriz. Bazı bilgiler, güvenli şekilde üzerine yazılmadan önce kısa bir süre yedeklerde kalabilir." },
    { t: "13. Bilgi Paylaşımı", b: "Kişisel bilgileri gelişigüzel paylaşmayız. Swipedia'yı işletmek, yasaya uymak veya meşru iş işlevlerini yerine getirmek için gerekli olduğunda bilgileri belirli alıcı kategorileriyle paylaşabiliriz. Bu kategoriler; bulut barındırma sağlayıcıları, veri tabanı sağlayıcıları, kimlik doğrulama sağlayıcıları, analiz sağlayıcıları, çökme raporlama sağlayıcıları, güvenlik sağlayıcıları, müşteri destek sağlayıcıları, ödeme sağlayıcıları, uygun olduğunda reklam sağlayıcıları, iletişim sağlayıcıları, profesyonel danışmanlar, yasal olarak gerektiğinde kamu kurumları ve yasal olarak izin verildiğinde kurumsal işlem tarafları olabilir. Üçüncü taraf sağlayıcılar bilgileri adımıza işleyebilir ve sözleşmesel ile yasal yükümlülüklere tabi olabilir." },
    { t: "14. Üçüncü Taraf Hizmet Sağlayıcıları", b: "Swipedia; kimlik doğrulama, bulut barındırma, veri tabanları, analiz, çökme raporlama, anlık bildirimler, reklamcılık, ödemeler, e-posta, güvenlik ve müşteri desteği için üçüncü taraf teknoloji sağlayıcıları kullanabilir. Üçüncü taraf sağlayıcıların güncel listesi, uygun olduğunda uygulama veya web sitesi üzerinden sunulabilir. Bu Gizlilik Politikası'nı, Swipedia'nın herhangi bir örnek veya şablonda listelenen her sağlayıcıyı kullandığı şeklinde yorumlamamalısın; yalnızca Swipedia'nın gerçekten kullandığı sağlayıcılar geçerlidir." },
    { t: "15. Reklamcılık", b: "Swipedia reklam gösterirse, geçerli hukuka ve tercihlerine tabi olarak reklamları sunmak ve ölçmek için gerekli bazı bilgileri alabilecek üçüncü taraf reklam sağlayıcıları kullanabiliriz. Yargı bölgesine ve teknolojiye bağlı olarak bu; cihaz bilgileri, reklam tanımlayıcıları, teknik bilgilerden türetilen yaklaşık konum, etkileşim bilgileri ve reklamla ilgili olayları içerebilir. Gerektiğinde kişiselleştirilmiş reklam için bilgileri kullanmadan önce onay alırız. Kullanıcıların, bazı geçerli yasalar kapsamında kişisel bilgilerin satışından veya paylaşımından vazgeçme konusunda ek hakları olabilir." },
    { t: "16. Analiz", b: "Hangi özelliklerin kullanıldığını, hangi kategorilerin popüler olduğunu, uygulamanın nasıl çalıştığını, çökmelerin nerede oluştuğunu, kullanıcıların uygulamada nasıl gezindiğini ve Hizmet'i nasıl iyileştirebileceğimizi anlamak için analiz teknolojileri kullanabiliriz. Analiz sağlayıcıları, teknik ve kullanım bilgilerini kendi koşullarına ve Swipedia ile yaptıkları geçerli anlaşmalara göre işleyebilir." },
    { t: "17. Uluslararası Veri Aktarımları", b: "Swipedia küresel bir hizmet olarak tasarlandığından, bilgiler yaşadığın ülke dışındaki ülkelerde işlenebilir veya saklanabilir. Geçerli hukuk uluslararası aktarımlar için güvence gerektirdiğinde uygun yasal mekanizmaları kullanırız. Avrupa Ekonomik Alanı, Birleşik Krallık veya benzer gerekliliklere sahip diğer yargı bölgelerindeki kullanıcılar için bunlar; geçerli yeterlilik kararlarını, sözleşmesel güvenceleri veya diğer yasal aktarım mekanizmalarını içerebilir." },
    { t: "18. GDPR Hakları", b: `GDPR sana uygulanıyorsa; bilgilendirilme hakkın, kişisel bilgilerine erişim, yanlış bilgilerin düzeltilmesi, silme talebi, işlemenin kısıtlanması, veri taşınabilirliği, belirli işlemelere itiraz, onaya dayalı işlemelerde onayı geri çekme ve belirli otomatik karar verme ile profillemeye ilişkin haklara sahip olabilirsin. Bu haklar geçerli yasal istisnalara tabidir. Haklarını kullanmak için iletişim: ${CONTACT_EMAIL}. Bazı talepleri tamamlamadan önce kimliğini doğrulamamız gerekebilir.` },
    { t: "19. Kaliforniya Gizlilik Hakları", b: `Kaliforniya sakiniysen ve geçerli Kaliforniya gizlilik yasası uygulanıyorsa; hangi kişisel bilgilerin toplandığını, nasıl kullanıldığını ve paylaşıldığını öğrenme; silme veya düzeltme talep etme; belirli satış ya da paylaşımdan vazgeçme; uygun olduğunda hassas kişisel bilgilerin belirli kullanımlarını sınırlandırma; ve gizlilik haklarını kullandığın için ayrımcı muamele görmeme hakkına sahip olabilirsin. Mevcudiyet geçerli hukuka bağlıdır. Talepler şu yollarla iletilebilir — E-posta: ${CONTACT_EMAIL} veya Gizlilik Talebi Sayfası: ${WEBSITE}.` },
    { t: "20. \"Satma veya Paylaşma\" ve Global Privacy Control", b: "Geçerli hukuk, kişisel bilgilerin satışı veya paylaşımı için bir vazgeçme mekanizması gerektirdiğinde Swipedia ilgili mekanizmayı sağlayacaktır. Yasal olarak gerekli ve teknik olarak desteklendiğinde, Global Privacy Control gibi geçerli tarayıcı veya cihaz gizlilik sinyallerini tanıyabiliriz. Bu tür mekanizmaların mevcudiyeti ve kapsamı, yargı bölgesine ve Swipedia'nın kullandığı teknolojilere bağlı olabilir." },
    { t: "21. Türk Kullanıcılar ve KVKK", b: `6698 sayılı Kişisel Verilerin Korunması Kanunu (\"KVKK\") sana uygulanıyorsa, Swipedia kişisel verileri geçerli gerekliliklere uygun olarak işleyecektir. KVKK kapsamında bireylerin; verilerinin işlenip işlenmediğini öğrenme, işlemeye ilişkin bilgi talep etme, işleme amaçlarını ve aktarıldığı tarafları öğrenme, uygun olduğunda düzeltme, silme veya yok etme talep etme ve kanunda sağlanan diğer haklar dâhil olmak üzere kişisel verilerine ilişkin hakları vardır. Swipedia; veri sorumlusunun kimliği, işleme amaçları, verilerin aktarılabileceği kişi veya kategoriler, toplama yöntemi ve hukuki dayanağı ile geçerli ilgili kişi hakları konusunda yasal olarak gerekli bilgileri sağlayacaktır. Talepler şu adrese gönderilebilir: ${CONTACT_EMAIL}.` },
    { t: "22. Çocukların Gizliliği", b: `Swipedia, geçerli hukuku ihlal edecek şekilde çocuklardan bilerek kişisel bilgi toplamayı amaçlamaz. Yaş şartları ülkeye göre değişebilir. İzin verilmeyen bir durumda bir çocuktan kişisel bilgi topladığımızı öğrenirsek, bu bilgiyi silmek için uygun adımları atabiliriz. Bir çocuğun kişisel bilgi sağladığına inanan ebeveynler veya yasal vasiler bize şu adresten ulaşabilir: ${CONTACT_EMAIL}.` },
    { t: "23. Veri Güvenliği", b: "Kişisel bilgileri yetkisiz erişime, kayba, kötüye kullanıma, değişikliğe veya ifşaya karşı korumak için; aktarım sırasında şifreleme, erişim kontrolleri, kimlik doğrulama mekanizmaları, izleme, güvenlik testi, altyapı korumaları ve diğer uygun güvenceler dâhil makul teknik ve organizasyonel önlemler kullanırız. Ancak hiçbir internet aktarımı veya depolama sistemi tamamen güvenli olacağı garanti edilemeyeceğinden mutlak güvenliği garanti edemeyiz." },
    { t: "24. Veri İhlalleri", b: "Kişisel bilgileri etkileyen bir güvenlik olayı meydana gelirse, geçerli hukukun gerektirdiği adımları atarız. Olayın niteliğine ve ciddiyetine bağlı olarak bu; olayı araştırma ve sınırlama, güvenlik önlemleri alma ve yasal olarak gerektiğinde etkilenen kişileri veya yetkilileri bilgilendirmeyi içerebilir." },
    { t: "25. Hesabın ve Veri Silme", b: `Uygun olduğunda Swipedia hesabının ve ilişkili kişisel bilgilerin silinmesini talep edebilirsin. Talebini ${WEBSITE} veya ${CONTACT_EMAIL} üzerinden iletebilirsin. Yasal uyum, güvenlik, dolandırıcılık önleme, uyuşmazlık çözümü veya yasal hakların uygulanması için gerekli bilgiler dâhil olmak üzere, yasanın gerektirdiği veya izin verdiği durumlarda bazı bilgilerin saklanması gerekebilir. Bilgi yedeklerde saklandığı için silme hemen mümkün olmadığında, bu bilgiler geçerli saklama ve güvenlik prosedürlerine göre işlenir.` },
    { t: "26. Veriye Erişim ve Düzeltme", b: `Hesabınla ilişkili bilgilerin yanlış veya eksik olduğuna inanıyorsan düzeltme talep edebilirsin. Özelliğe bağlı olarak bazı bilgileri doğrudan uygulama içinde de değiştirebilirsin. Talepler şu adrese iletilebilir: ${CONTACT_EMAIL}.` },
    { t: "27. Pazarlama İletişimleri", b: "Geçerli hukukun izin verdiği durumlarda Swipedia tanıtım iletişimleri gönderebilir. İletişimdeki abonelikten çıkma mekanizmasını veya mevcut hesap ayarlarını kullanarak pazarlama iletişimlerinden çıkabilirsin. Pazarlama iletişimlerinden vazgeçsen bile güvenlik bildirimleri, hesap bildirimleri veya önemli yasal güncellemeler gibi temel hizmetle ilgili mesajları göndermeye devam edebiliriz." },
    { t: "28. Otomatik Karar Verme ve Profilleme", b: "Swipedia; soruları düzenlemek, sıralamak veya önermek için otomatik sistemler kullanabilir. Örneğin sistem, hangi soruların veya kategorilerin sana gösterilebileceğini belirlemek için önceki etkileşimlerini kullanabilir. Bu sistemler içerik keşfini ve kişiselleştirmeyi iyileştirmek içindir. Aksi belirtilmedikçe Swipedia, bu sistemlerin kullanıcılar üzerinde hukuki veya benzer şekilde önemli etkiler doğuran kararlar vermesini amaçlamaz. Geçerli hukuk otomatik karar verme veya profillemeye ilişkin belirli haklar sağladığında bu haklar kullanılabilir kalır." },
    { t: "29. Kullanıcı Tarafından Oluşturulan Bilgiler", b: "Swipedia; kullanıcıların bilgi, soru, yorum, profil, geri bildirim veya başka içerik göndermesine olanak tanıyan özellikler sunarsa, bu bilgiler söz konusu özellikleri sağlamak için gerektiği şekilde işlenebilir. Kullanıcılar, ilgili özellik özellikle gerektirmedikçe ve uygun güvenceler sağlanmadıkça hassas kişisel bilgi göndermekten kaçınmalıdır." },
    { t: "30. Herkese Açık Bilgiler", b: "Swipedia; herkese açık profiller, liderlik tabloları, sıralamalar, başarımlar veya başka açık özellikler sunarsa, özelliğe ve ayarlarına bağlı olarak bazı bilgiler diğer kullanıcılara görünür hâle gelebilir. Bilgileri herkese açık hâle getirmeden önce Swipedia, gerektiğinde uygun bilgileri veya kontrolleri sağlayacaktır." },
    { t: "31. Yasal İfşalar", b: "Yasal yükümlülüklere uymak, yasal taleplere yanıt vermek, kullanıcıların haklarını veya güvenliğini korumak, Swipedia'yı korumak, dolandırıcılık veya kötüye kullanımı araştırmak, Koşullar'ımızı uygulamak ya da yasal süreçlere yanıt vermek için makul olarak gerekli olduğunda bilgileri ifşa edebiliriz. Ayrıca geçerli hukuka tabi olarak birleşme, satın alma, finansman, yeniden yapılanma, varlık satışı veya benzeri kurumsal işlemlerle bağlantılı olarak da bilgileri ifşa edebiliriz." },
    { t: "32. Üçüncü Taraf Bağlantıları", b: "Swipedia, üçüncü taraf web sitelerine veya hizmetlerine bağlantılar içerebilir. Üçüncü taraf web sitelerinin gizlilik uygulamalarından sorumlu değiliz. Kişisel bilgi vermeden önce üçüncü taraf hizmetlerin gizlilik politikalarını incelemeni öneririz." },
    { t: "33. Hesap Silme Sonrası Veri Saklama", b: "Bir hesap silindiğinde, ilişkili bilgileri geçerli saklama prosedürlerimize göre işleriz. Bazı bilgiler; yasal yükümlülükler, dolandırıcılık önleme, güvenlik, muhasebe, uyuşmazlık çözümü, sözleşmelerin uygulanması veya yedekleme sistemleri nedeniyle kısa bir süre kalabilir. Saklama gerektiğinde, yasa aksine izin vermedikçe bilgiler ilgili amaç için gerekli olandan daha uzun süre saklanmaz." },
    { t: "34. Bu Gizlilik Politikasındaki Değişiklikler", b: "Bu Gizlilik Politikası'nı zaman zaman güncelleyebiliriz. Önemli değişiklikler yaparsak kullanıcıları uygulama, web sitemiz, e-posta, uygulama içi bildirim veya başka uygun bir yöntemle bilgilendirebiliriz. Üstteki \"Son Güncelleme\" tarihi, politikanın en son ne zaman revize edildiğini gösterir." },
    { t: "35. Bize Ulaşın", b: `Bu Gizlilik Politikası veya kişisel bilgilerin hakkında sorun varsa bize ulaş:\nSwipedia Gizlilik E-postası: ${CONTACT_EMAIL}\nGenel İletişim: ${GENERAL_EMAIL}\nWeb sitesi: ${WEBSITE}` },
    { t: "36. Veri Koruma Kurumu Şikâyetleri", b: "Bulunduğun yere bağlı olarak yerel veri koruma kurumuna şikâyette bulunma hakkına sahip olabilirsin. Avrupa Ekonomik Alanı'ndaki kullanıcılar için ilgili denetim makamı; yaşadığın, çalıştığın veya bir ihlalin gerçekleştiğine inandığın ülkedeki veri koruma kurumu olabilir. Bu hak, önce endişenle ilgili olarak Swipedia ile iletişime geçmeni engellemez." },
    { t: "37. Son Bildirim", b: "Bu Gizlilik Politikası; Swipedia'nın gerçekten kullandığı özelliklere ve teknolojilere dayanan amaçlanan gizlilik uygulamalarını açıklar. Swipedia, kişisel bilgilerin nasıl toplandığını veya kullanıldığını önemli ölçüde değiştiren yeni özellikler sunarsa bu Gizlilik Politikası buna göre güncellenebilir." },
  ],
};

export function getLegal(doc: "terms" | "privacy", lang: string): LegalDoc {
  const isTr = lang === "tr";
  if (doc === "terms") return isTr ? TERMS_TR : TERMS_EN;
  return isTr ? PRIVACY_TR : PRIVACY_EN;
}
